const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity?: number }> = ({ shape, color, opacity = 0.5 }) => {
    const outlines = useMemo(() => {
        const points = shape.points;
        const h = shape.height;
        const topLoop: [number, number, number][] = [];
        const bottomLoop: [number, number, number][] = [];
        const verticals: [number, number, number][][] = [];

        const len = points.length;
        if (len < 2) return null;

        for (let i = 0; i < len; i++) {
            const curr = points[i];
            const next = points[(i + 1) % len];
            const prev = points[(i - 1 + len) % len];

            const v1 = new THREE.Vector2(curr.x - prev.x, (-curr.z) - (-prev.z)).normalize();
            const v2 = new THREE.Vector2(next.x - curr.x, (-next.z) - (-curr.z)).normalize();
            const dot = v1.dot(v2);

            const x = curr.x;
            const y = -curr.z;

            topLoop.push([x, y, h]);
            bottomLoop.push([x, y, 0]);

            if (dot < 0.9) {
                verticals.push([[x, y, 0], [x, y, h]]);
            }
        }

        if (topLoop.length > 0) topLoop.push(topLoop[0]);
        if (bottomLoop.length > 0) bottomLoop.push(bottomLoop[0]);

        return { topLoop, bottomLoop, verticals };
    }, [shape]);

    if (!outlines) return null;

    return (
        <group rotation={[-Math.PI / 2, 0, 0]}>
             <Line points={outlines.topLoop} color={color} lineWidth={2} transparent opacity={opacity} depthTest={true} />
             <Line points={outlines.bottomLoop} color={color} lineWidth={2} transparent opacity={opacity * 0.5} depthTest={true} />
             {outlines.verticals.map((pts, i) => (
                 <Line key={i} points={pts} color={color} lineWidth={2} transparent opacity={opacity} depthTest={true} />
             ))}
        </group>
    );
};

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        isDragging: boolean;
        ppState: PushPullState;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
}

const ShapeRenderer: React.FC<ShapeRendererProps> = ({ shape, isSelected, onSelect, pushPullHandlers, drawingHandlers }) => {
    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const { unit, tool } = useApp();
    const [hovered, setHovered] = useState(false);

    if (shape.type === 'dimension') {
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <Line points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1], shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id }} 
            name="shape_group" 
            onClick={!isPushPullMode ? onSelect : undefined}
            onPointerOver={(e) => { 
                e.stopPropagation(); 
                setHovered(true); 
            }}
            onPointerOut={() => { 
                setHovered(false); 
                document.body.style.cursor = 'default'; 
            }}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={isPushPullMode ? pushPullHandlers.handlePointerMove : undefined}
            onPointerUp={(e) => {
                pushPullHandlers.handlePointerUp();
                drawingHandlers.handlePointerUp(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
};

