                onPointerDown={drawingTools.handlePointerDown}
                onPointerUp={drawingTools.handlePointerUp}
                onPointerMove={tool === ToolType.PUSH_PULL ? pushPullManager.handlePointerMove : undefined}
            >
                <planeGeometry args={[200, 200]} />
                <meshBasicMaterial visible={false} />
            </mesh>

            <group>
                {shapes.map(shape => (
                    <ShapeRenderer 
                        key={shape.id} 
                        shape={shape} 
                        isSelected={selectedIds.includes(shape.id)} 
                        onSelect={(e) => handleShapeClick(e, shape.id)} 
                        pushPullHandlers={pushPullManager}
                        drawingHandlers={{
                            handlePointerDown: drawingTools.handlePointerDown,
