import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number; // For side push/pull
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[]; // Snapshot of points before drag
    normal: THREE.Vector3; // Normal of the face we are pulling
}

// --- Geometry Helpers ---

// Check if two shapes are coplanar (Focusing on the base plane Y-level)
const areShapesCoplanar = (shapeA: IShape, shapeB: IShape): boolean => {
    // 1. Check Vertical Alignment (Y-axis) for base plane
    const yDiff = Math.abs(shapeA.position[1] - shapeB.position[1]);
    return yDiff < EPSILON;
};

// Check if a 3D point lies on the geometric plane of a Shape's face
const isPointOnShapePlane = (point: THREE.Vector3, shape: IShape, mode: 'top' | 'side' = 'top'): boolean => {
    if (mode === 'top') {
        const currentH = shape.height * shape.scale[1];
        const topY = shape.position[1] + currentH;
        const baseY = shape.position[1];
        return Math.abs(point.y - topY) < EPSILON || Math.abs(point.y - baseY) < EPSILON;
    }
    return false; 
};

// 2D Cross product (determinant)
const crossProduct = (a: IPoint, b: IPoint, o: IPoint) => {
    return (a.x - o.x) * (b.z - o.z) - (a.z - o.z) * (b.x - o.x);
};

// Check if point is on segment
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false;
    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false;
    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false;
    return true;
};

// Get intersection of two line segments (AB and CD)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel

    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return {
            x: p1.x + u * (p2.x - p1.x),
            y: 0,
            z: p1.z + u * (p2.z - p1.z)
        };
    }
    return null;
};

// Split a polygon by a line segment (cutStart -> cutEnd)
const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    // 1. Find intersections
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];

    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;

            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    if (intersections.length !== 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;

    // 2. Construct two new polygons
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }

    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);

    if (idx1 === -1 || idx2 === -1) return null;

    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);

    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];

    return [polyA, polyB];
};

const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const relX = worldP.x - shape.position[0];
    const relZ = worldP.z - shape.position[2];

    const rot = -shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xRot = relX * cos - relZ * sin;
    const zRot = relX * sin + relZ * cos;

    return {
        x: xRot / shape.scale[0],
        y: 0,
        z: zRot / shape.scale[2]
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;

  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;

  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;

  if (l2 === 0) return v;

  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));

  return new THREE.Vector3(
    v.x + t * vwx,
    v.y + t * vwy,
    v.z + t * vwz
  );
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    const distSq = (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
    return distSq;
};

// --- Geometry Snapping Logic ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;
    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));
    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) { minDiffX = diffX; alignX = pt.x; guideXSrc = pt; }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) { minDiffZ = diffZ; alignZ = pt.z; guideZSrc = pt; }
    }
    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;
        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        if (alignZ !== null && guideZSrc) guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        return { position: snappedPos, type: 'align', distance: 0, guides };
    }

    return bestSnap;
};

