const usePushPullManager = () => {
    const { tool, updateShape, shapes } = useApp();
    const { camera, gl } = useThree();

    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = (e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const object = e.object;
        let curr: THREE.Object3D | null = object;
        let shapeId: string | null = null;
        while(curr) {
            if (curr.userData?.isShape) {
                shapeId = curr.userData.id;
                break;
            }
            curr = curr.parent;
        }
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;

        const intersection = e.intersections[0];
        if (!intersection || !intersection.face) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        if (worldNormal.y > 0.9) {
            return {
                mode: 'top',
                hoveredShapeId: shapeId,
                hoveredEdgeIndex: -1,
                normal: new THREE.Vector3(0, 1, 0)
            };
        }

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);

            let closestIndex = -1;
            let minDistSq = Infinity;

            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];

                const d2 = distToSegmentSquared(
                    new THREE.Vector3(unscaledX, 0, unscaledZ),
                    new THREE.Vector3(p1.x, 0, p1.z),
                    new THREE.Vector3(p2.x, 0, p2.z)
                );

                if (d2 < minDistSq) {
                    minDistSq = d2;
                    closestIndex = i;
                }
            }

            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return {
                    mode: 'side',
                    hoveredShapeId: shapeId,
                    hoveredEdgeIndex: closestIndex,
                    normal: flatNormal
                };
            }
        }

        return null;
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
            ), camera);

            if (ppState.mode === 'top') {
                const planeNormal = new THREE.Vector3();
                camera.getWorldDirection(planeNormal).setY(0).normalize(); 
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                   camera.getWorldDirection(new THREE.Vector3()).negate(), 
                   ppState.dragStartPoint
                );

                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    updateShape(shape.id, { height: newHeight });
                }

            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);

                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];

                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];

                    p1.x += dLocalX;
                    p1.z += dLocalZ;
                    p2.x += dLocalX;
                    p2.z += dLocalZ;

                    updateShape(shape.id, { points: newPoints });
                }
            }

        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ 
                    ...prev, 
                    mode: res.mode!, 
                    hoveredShapeId: res.hoveredShapeId!, 
                    hoveredEdgeIndex: res.hoveredEdgeIndex!,
                    normal: res.normal!
                }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();

        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
             ), camera);

             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                     camera.getWorldDirection(new THREE.Vector3()).negate(),
                     e.point
                 );
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }

             setPPState(prev => ({
                 ...prev,
                 dragStartPoint: startPoint,
                 originalHeight: shape.height,
                 originalPoints: JSON.parse(JSON.stringify(shape.points))
             }));
        }
    };

    const handlePointerUp = () => {
        if (isDragging) {
            setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [] }));
        }
    };

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes } = useApp();
    const { scene } = useThree();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
    }, [tool]);

    // Add Escape key handler
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setDrawPoints([]);
                setIsDragging(false);
                if (tool !== ToolType.SELECT) {
                    setTool(ToolType.SELECT);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, setTool]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;

        if (tool === ToolType.DRAW_RECT) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const width = Math.abs(end.x - start.x);
                 const depth = Math.abs(end.z - start.z);
                 if (width >= 0.01 && depth >= 0.01) {
                     const cx = (start.x + end.x) / 2;
                     const cz = (start.z + end.z) / 2;

                     const points = [
                         { x: -width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: depth/2 },
                         { x: -width/2, y: 0, z: depth/2 },
                     ];

                     addShape({
                         id: `rect-${Date.now()}`,
                         type: 'solid',
                         name: 'Area',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [cx, 0, cz],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_CIRCLE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createCirclePoints(radius);
                     addShape({
                         id: `circle-${Date.now()}`,
                         type: 'solid',
                         name: 'Circle',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [start.x, 0, start.z],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_ARC) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createArcPoints(radius);
                     const angle = Math.atan2(end.z - start.z, end.x - start.x);

                     addShape({
                        id: `arc-${Date.now()}`,
                        type: 'flat',
                        name: 'Door Swing',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, 0, start.z],
                        rotation: -angle, 
                        scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_LINE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

                 if (dist >= 0.01) {
                     let splitOccurred = false;

                     for (let i = shapes.length - 1; i >= 0; i--) {
                         const targetShape = shapes[i];
                         if (targetShape.type === 'dimension') continue;

                         const localStart = inverseTransformPoint(new THREE.Vector3(start.x, 0, start.z), targetShape);
                         const localEnd = inverseTransformPoint(new THREE.Vector3(end.x, 0, end.z), targetShape);

                         const splitResult = splitPolygonByLine(targetShape.points, localStart, localEnd);

                         if (splitResult) {
                             const [polyA, polyB] = splitResult;

                             const shapeA: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-a`,
                                 points: polyA,
                                 name: targetShape.name
                             };
                             const shapeB: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-b`,
                                 points: polyB,
                                 name: targetShape.name
                             };

                             replaceShapes([targetShape.id], [shapeA, shapeB]);
                             splitOccurred = true;
                             break;
                         }
                     }

                     if (!splitOccurred) {
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.2;

                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;

                        const halfL = dist / 2;
                        const halfW = thickness / 2;

                        const points = [
                            { x: -halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: halfW },
                            { x: -halfL, y: 0, z: halfW },
                        ];

                        addShape({
                           id: `wall-${Date.now()}`,
                           type: 'solid',
                           name: 'Wall',
                           points,
                           height: DEFAULT_HEIGHT,
                           color: DEFAULT_COLOR,
                           position: [cx, 0, cz],
                           rotation: -angle, 
                           scale: [1, 1, 1]
                        });
                     }
                     shapeCreated = true;
                     // Continuous Line: Set start point to end point for next segment
                     setDrawPoints([{ x: end.x, y: 0, z: end.z }]);
                     return; // Don't clear drawPoints
                 }
             }

        } else if (tool === ToolType.DRAW_POLY) {
             if (finalPoints.length >= 3) {
                 const cx = finalPoints.reduce((s, pt) => s + pt.x, 0) / finalPoints.length;
                 const cz = finalPoints.reduce((s, pt) => s + pt.z, 0) / finalPoints.length;

                 const localPoints = finalPoints.map(pt => ({ x: pt.x - cx, y: 0, z: pt.z - cz }));

                 addShape({
                    id: `poly-${Date.now()}`,
                    type: 'solid',
                    name: 'Polygon',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: DEFAULT_COLOR,
                    position: [cx, 0, cz],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.MEASURE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 addShape({
                    id: `dim-${Date.now()}`,
                    type: 'dimension',
                    name: 'Dimension',
                    points: [start, end],
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        }
        setDrawPoints([]);

        if (shapeCreated) {
            setTool(ToolType.SELECT);
        }

    }, [tool, addShape, wallThickness, setTool, shapes, replaceShapes]);

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        const groundNormal = new THREE.Vector3(0, 1, 0);
        const plane = new THREE.Plane(groundNormal, 0);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);

        if (hit) {
            const intersects = raycaster.intersectObjects(scene.children, true);
            const firstObjHit = intersects.find(i => i.object.userData?.isShape);

            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, firstObjHit);

            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }

            if (isDragging) {
                const currentP = { x: snap.position.x, y: 0, z: snap.position.z };

                 if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
                     setDrawPoints(prev => {
                         if (prev.length === 0) return [currentP];
                         return [prev[0], currentP];
                     });
                }
                // Removed DRAW_LINE from here since it uses click-click now
            }
        }
    });

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        if (e.button === 0) {
            e.stopPropagation();

            if (tool === ToolType.DRAW_POLY) {
                 const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                 if (drawPoints.length > 2) {
                     const first = drawPoints[0];
                     const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                     if (dist < SNAP_THRESHOLD) {
                         finishShape(drawPoints);
                         return;
                     }
                 }
                 setDrawPoints(prev => [...prev, p]);
            } 
            else if (tool === ToolType.DRAW_LINE) {
                // Continuous Line Logic (Click-Click)
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                if (drawPoints.length === 0) {
                     setDrawPoints([p]);
                } else {
                     // Finish segment
                     finishShape([drawPoints[0], p]);
                }
            }
            else {
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                setDrawPoints([p]);
                setIsDragging(true);
            }
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
         if (isDragging && e.button === 0) {
             e.stopPropagation();
             setIsDragging(false);

             // DRAW_LINE handled in PointerDown now
             if (tool !== ToolType.DRAW_POLY && tool !== ToolType.DRAW_LINE) {
                 if (drawPoints.length > 1) {
                     const start = drawPoints[0];
                     const end = drawPoints[drawPoints.length - 1];
                     const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (dist > 0.01) {
                        finishShape(drawPoints);
                     } else {
                         setDrawPoints([]);
                     }
                 }
             }
         }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        return;
    };

    return {
        handleClick,
        handlePointerDown,
        handlePointerUp,
        drawPoints,
        cursorPos,
        snapInfo,
        tool,
        isDragging
    };
};

const DrawingVisuals: React.FC<{ drawPoints: IPoint[], cursorPos: THREE.Vector3, snapInfo: SnapResult | null, tool: ToolType }> = ({ drawPoints, cursorPos, snapInfo, tool }) => {
    const { formatValue } = useApp();

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + 0.05, p.z));

    let previewShape: React.ReactElement | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];
        const currentEnd = points.length > 1 ? points[points.length - 1] : new THREE.Vector3(cursorPos.x, cursorPos.y + 0.05, cursorPos.z);

        if (tool === ToolType.DRAW_LINE) {
             const dist = start.distanceTo(currentEnd);
             infoText = `L: ${formatValue(dist)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_POLY) {
            const pointsToRender = [...points, currentEnd];

            if(points.length > 0) {
                 const last = points[points.length - 1];
                 const dist = last.distanceTo(currentEnd);
                 infoText = `L: ${formatValue(dist)}`;
            }

            let closeLoop = false;
            if (points.length > 2) {
                 if (start.distanceTo(currentEnd) < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                     closeLoop = true;
                 }
            }

            previewShape = (
                <>
                    <Line points={pointsToRender} color="black" lineWidth={2} />
                    {closeLoop && <mesh position={start}><sphereGeometry args={[0.15]} /><meshBasicMaterial color="#facc15" /></mesh>}
                </>
            );
        } else if (tool === ToolType.MEASURE) {
            const dist = start.distanceTo(currentEnd);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <Line points={[start, currentEnd]} color={DIMENSION_COLOR} lineWidth={2} dashed dashScale={10} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(currentEnd.x - start.x);
             const depth = Math.abs(currentEnd.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;

             const p1 = start;
             const p2 = new THREE.Vector3(currentEnd.x, start.y, start.z);
             const p3 = currentEnd;
             const p4 = new THREE.Vector3(start.x, start.y, currentEnd.z);

             previewShape = <Line points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;

             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <Line points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else {
                 infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
             }
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}

            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}

            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip 
                    text={infoText || snapInfo!.type} 
                    position={cursorPos} 
                    type={snapInfo?.type} 
                 />
            )}

            {snapInfo?.guides?.map((guide, i) => (
                <Line key={i} points={guide} color="#a855f7" lineWidth={1} dashed dashScale={5} />
            ))}
        </group>
    );
};

