import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number; // For side push/pull
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[]; // Snapshot of points before drag
    normal: THREE.Vector3; // Normal of the face we are pulling
}

// --- Geometry Helpers ---

// Check if two shapes are coplanar (Focusing on the base plane Y-level)
const areShapesCoplanar = (shapeA: IShape, shapeB: IShape): boolean => {
    // 1. Check Vertical Alignment (Y-axis) for base plane
    const yDiff = Math.abs(shapeA.position[1] - shapeB.position[1]);
    return yDiff < EPSILON;
};

// Check if a 3D point lies on the geometric plane of a Shape's face
const isPointOnShapePlane = (point: THREE.Vector3, shape: IShape, mode: 'top' | 'side' = 'top'): boolean => {
    if (mode === 'top') {
        const currentH = shape.height * shape.scale[1];
        const topY = shape.position[1] + currentH;
        const baseY = shape.position[1];
        return Math.abs(point.y - topY) < EPSILON || Math.abs(point.y - baseY) < EPSILON;
    }
    return false; 
};

// 2D Cross product (determinant)
const crossProduct = (a: IPoint, b: IPoint, o: IPoint) => {
    return (a.x - o.x) * (b.z - o.z) - (a.z - o.z) * (b.x - o.x);
};

// Check if point is on segment
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false;
    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false;
    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false;
    return true;
};

// Get intersection of two line segments (AB and CD)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel

    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return {
            x: p1.x + u * (p2.x - p1.x),
            y: 0,
            z: p1.z + u * (p2.z - p1.z)
        };
    }
    return null;
};

// Split a polygon by a line segment (cutStart -> cutEnd)
const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    // 1. Find intersections
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];

    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;

            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    if (intersections.length !== 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;

    // 2. Construct two new polygons
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }

    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);

    if (idx1 === -1 || idx2 === -1) return null;

    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);

    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];

    return [polyA, polyB];
};

const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const relX = worldP.x - shape.position[0];
    const relZ = worldP.z - shape.position[2];

    const rot = -shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xRot = relX * cos - relZ * sin;
    const zRot = relX * sin + relZ * cos;

    return {
        x: xRot / shape.scale[0],
        y: 0,
        z: zRot / shape.scale[2]
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;

  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;

  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;

  if (l2 === 0) return v;

  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));

  return new THREE.Vector3(
    v.x + t * vwx,
    v.y + t * vwy,
    v.z + t * vwz
  );
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    const distSq = (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
    return distSq;
};

// --- Geometry Snapping Logic ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;
    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));
    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) { minDiffX = diffX; alignX = pt.x; guideXSrc = pt; }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) { minDiffZ = diffZ; alignZ = pt.z; guideZSrc = pt; }
    }
    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;
        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        if (alignZ !== null && guideZSrc) guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        return { position: snappedPos, type: 'align', distance: 0, guides };
    }

    return bestSnap;
};

// --- Custom Hooks & Components ---

const usePushPullManager = () => {
    const { tool, updateShape, shapes } = useApp();
    const { camera, gl } = useThree();

    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = (e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const object = e.object;
        let curr: THREE.Object3D | null = object;
        let shapeId: string | null = null;
        while(curr) {
            if (curr.userData?.isShape) {
                shapeId = curr.userData.id;
                break;
            }
            curr = curr.parent;
        }
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;

        const intersection = e.intersections[0];
        if (!intersection || !intersection.face) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        if (worldNormal.y > 0.9) {
            return {
                mode: 'top',
                hoveredShapeId: shapeId,
                hoveredEdgeIndex: -1,
                normal: new THREE.Vector3(0, 1, 0)
            };
        }

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);

            let closestIndex = -1;
            let minDistSq = Infinity;

            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];

                const d2 = distToSegmentSquared(
                    new THREE.Vector3(unscaledX, 0, unscaledZ),
                    new THREE.Vector3(p1.x, 0, p1.z),
                    new THREE.Vector3(p2.x, 0, p2.z)
                );

                if (d2 < minDistSq) {
                    minDistSq = d2;
                    closestIndex = i;
                }
            }

            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return {
                    mode: 'side',
                    hoveredShapeId: shapeId,
                    hoveredEdgeIndex: closestIndex,
                    normal: flatNormal
                };
            }
        }

        return null;
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
            ), camera);

            if (ppState.mode === 'top') {
                const planeNormal = new THREE.Vector3();
                camera.getWorldDirection(planeNormal).setY(0).normalize(); 
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                   camera.getWorldDirection(new THREE.Vector3()).negate(), 
                   ppState.dragStartPoint
                );

                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    updateShape(shape.id, { height: newHeight });
                }

            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);

                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];

                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];

                    p1.x += dLocalX;
                    p1.z += dLocalZ;
                    p2.x += dLocalX;
                    p2.z += dLocalZ;

                    updateShape(shape.id, { points: newPoints });
                }
            }

        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ 
                    ...prev, 
                    mode: res.mode!, 
                    hoveredShapeId: res.hoveredShapeId!, 
                    hoveredEdgeIndex: res.hoveredEdgeIndex!,
                    normal: res.normal!
                }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();

        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
             ), camera);

             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                     camera.getWorldDirection(new THREE.Vector3()).negate(),
                     e.point
                 );
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }

             setPPState(prev => ({
                 ...prev,
                 dragStartPoint: startPoint,
                 originalHeight: shape.height,
                 originalPoints: JSON.parse(JSON.stringify(shape.points))
             }));
        }
    };

    const handlePointerUp = () => {
        if (isDragging) {
            setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [] }));
        }
    };

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes } = useApp();
    const { scene } = useThree();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
    }, [tool]);

    // Add Escape key handler
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setDrawPoints([]);
                setIsDragging(false);
                if (tool !== ToolType.SELECT) {
                    setTool(ToolType.SELECT);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, setTool]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;

        if (tool === ToolType.DRAW_RECT) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const width = Math.abs(end.x - start.x);
                 const depth = Math.abs(end.z - start.z);
                 if (width >= 0.01 && depth >= 0.01) {
                     const cx = (start.x + end.x) / 2;
                     const cz = (start.z + end.z) / 2;

                     const points = [
                         { x: -width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: depth/2 },
                         { x: -width/2, y: 0, z: depth/2 },
                     ];

                     addShape({
                         id: `rect-${Date.now()}`,
                         type: 'solid',
                         name: 'Area',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [cx, 0, cz],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_CIRCLE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createCirclePoints(radius);
                     addShape({
                         id: `circle-${Date.now()}`,
                         type: 'solid',
                         name: 'Circle',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [start.x, 0, start.z],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_ARC) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createArcPoints(radius);
                     const angle = Math.atan2(end.z - start.z, end.x - start.x);

                     addShape({
                        id: `arc-${Date.now()}`,
                        type: 'flat',
                        name: 'Door Swing',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, 0, start.z],
                        rotation: -angle, 
                        scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_LINE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

                 if (dist >= 0.01) {
                     let splitOccurred = false;

                     for (let i = shapes.length - 1; i >= 0; i--) {
                         const targetShape = shapes[i];
                         if (targetShape.type === 'dimension') continue;

                         const localStart = inverseTransformPoint(new THREE.Vector3(start.x, 0, start.z), targetShape);
                         const localEnd = inverseTransformPoint(new THREE.Vector3(end.x, 0, end.z), targetShape);

                         const splitResult = splitPolygonByLine(targetShape.points, localStart, localEnd);

                         if (splitResult) {
                             const [polyA, polyB] = splitResult;

                             const shapeA: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-a`,
                                 points: polyA,
                                 name: targetShape.name
                             };
                             const shapeB: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-b`,
                                 points: polyB,
                                 name: targetShape.name
                             };

                             replaceShapes([targetShape.id], [shapeA, shapeB]);
                             splitOccurred = true;
                             break;
                         }
                     }

                     if (!splitOccurred) {
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.2;

                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;

                        const halfL = dist / 2;
                        const halfW = thickness / 2;

                        const points = [
                            { x: -halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: halfW },
                            { x: -halfL, y: 0, z: halfW },
                        ];

                        addShape({
                           id: `wall-${Date.now()}`,
                           type: 'solid',
                           name: 'Wall',
                           points,
                           height: DEFAULT_HEIGHT,
                           color: DEFAULT_COLOR,
                           position: [cx, 0, cz],
                           rotation: -angle, 
                           scale: [1, 1, 1]
                        });
                     }
                     shapeCreated = true;
                     // Continuous Line: Set start point to end point for next segment
                     setDrawPoints([{ x: end.x, y: 0, z: end.z }]);
                     return; // Don't clear drawPoints
                 }
             }

        } else if (tool === ToolType.DRAW_POLY) {
             if (finalPoints.length >= 3) {
                 const cx = finalPoints.reduce((s, pt) => s + pt.x, 0) / finalPoints.length;
                 const cz = finalPoints.reduce((s, pt) => s + pt.z, 0) / finalPoints.length;

                 const localPoints = finalPoints.map(pt => ({ x: pt.x - cx, y: 0, z: pt.z - cz }));

                 addShape({
                    id: `poly-${Date.now()}`,
                    type: 'solid',
                    name: 'Polygon',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: DEFAULT_COLOR,
                    position: [cx, 0, cz],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.MEASURE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 addShape({
                    id: `dim-${Date.now()}`,
                    type: 'dimension',
                    name: 'Dimension',
                    points: [start, end],
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        }
        setDrawPoints([]);

        if (shapeCreated) {
            setTool(ToolType.SELECT);
        }

    }, [tool, addShape, wallThickness, setTool, shapes, replaceShapes]);

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        const groundNormal = new THREE.Vector3(0, 1, 0);
        const plane = new THREE.Plane(groundNormal, 0);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);

        if (hit) {
            const intersects = raycaster.intersectObjects(scene.children, true);
            const firstObjHit = intersects.find(i => i.object.userData?.isShape);

            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, firstObjHit);

            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }

            if (isDragging) {
                const currentP = { x: snap.position.x, y: 0, z: snap.position.z };

                 if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
                     setDrawPoints(prev => {
                         if (prev.length === 0) return [currentP];
                         return [prev[0], currentP];
                     });
                }
                // Removed DRAW_LINE from here since it uses click-click now
            }
        }
    });

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        if (e.button === 0) {
            e.stopPropagation();

            if (tool === ToolType.DRAW_POLY) {
                 const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                 if (drawPoints.length > 2) {
                     const first = drawPoints[0];
                     const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                     if (dist < SNAP_THRESHOLD) {
                         finishShape(drawPoints);
                         return;
                     }
                 }
                 setDrawPoints(prev => [...prev, p]);
            } 
            else if (tool === ToolType.DRAW_LINE) {
                // Continuous Line Logic (Click-Click)
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                if (drawPoints.length === 0) {
                     setDrawPoints([p]);
                } else {
                     // Finish segment
                     finishShape([drawPoints[0], p]);
                }
            }
            else {
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                setDrawPoints([p]);
                setIsDragging(true);
            }
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
         if (isDragging && e.button === 0) {
             e.stopPropagation();
             setIsDragging(false);

             // DRAW_LINE handled in PointerDown now
             if (tool !== ToolType.DRAW_POLY && tool !== ToolType.DRAW_LINE) {
                 if (drawPoints.length > 1) {
                     const start = drawPoints[0];
                     const end = drawPoints[drawPoints.length - 1];
                     const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (dist > 0.01) {
                        finishShape(drawPoints);
                     } else {
                         setDrawPoints([]);
                     }
                 }
             }
         }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        return;
    };

    return {
        handleClick,
        handlePointerDown,
        handlePointerUp,
        drawPoints,
        cursorPos,
        snapInfo,
        tool,
        isDragging
    };
};

// --- New Components to fix errors ---

const SnapIndicator: React.FC<{ position: THREE.Vector3, type: SnapType, snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none') return null;

    // Different colors for snap types
    const color = 
        type === 'vertex' ? '#ef4444' : // Red
        type === 'midpoint' ? '#06b6d4' : // Cyan
        type === 'edge' ? '#ef4444' : // Red
        type === 'face' ? '#3b82f6' : // Blue
        type === 'grid' ? '#64748b' : // Slate
        '#a855f7'; // Purple (Align)

    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' || type === 'midpoint' ? 0.08 : 0.05]} />
                <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
            </mesh>
            {type === 'midpoint' && (
                <mesh>
                    <boxGeometry args={[0.12, 0.12, 0.12]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
                </mesh>
            )}
             {snapEdge && (
                 <Line points={[snapEdge[0], snapEdge[1]]} color={color} lineWidth={2} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string, position: THREE.Vector3, type?: string }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.2, position.z]} center style={{ pointerEvents: 'none', whiteSpace: 'nowrap' }}>
            <div className={`px-2 py-1 rounded text-[10px] font-bold shadow-sm backdrop-blur-sm border border-white/20
                ${type === 'align' ? 'bg-purple-600/90 text-white' : 
                  type === 'midpoint' ? 'bg-cyan-600/90 text-white' :
                  type === 'vertex' ? 'bg-red-600/90 text-white' :
                  'bg-slate-800/90 text-white'}`}>
                {text}
            </div>
        </Html>
    );
};

const DrawingVisuals: React.FC<{ drawPoints: IPoint[], cursorPos: THREE.Vector3, snapInfo: SnapResult | null, tool: ToolType }> = ({ drawPoints, cursorPos, snapInfo, tool }) => {
    const { formatValue } = useApp();

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + 0.05, p.z));

    let previewShape: React.ReactElement | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];
        const currentEnd = points.length > 1 ? points[points.length - 1] : new THREE.Vector3(cursorPos.x, cursorPos.y + 0.05, cursorPos.z);

        if (tool === ToolType.DRAW_LINE) {
             const dist = start.distanceTo(currentEnd);
             infoText = `L: ${formatValue(dist)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_POLY) {
            const pointsToRender = [...points, currentEnd];

            if(points.length > 0) {
                 const last = points[points.length - 1];
                 const dist = last.distanceTo(currentEnd);
                 infoText = `L: ${formatValue(dist)}`;
            }

            let closeLoop = false;
            if (points.length > 2) {
                 if (start.distanceTo(currentEnd) < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                     closeLoop = true;
                 }
            }

            previewShape = (
                <>
                    <Line points={pointsToRender} color="black" lineWidth={2} />
                    {closeLoop && <mesh position={start}><sphereGeometry args={[0.15]} /><meshBasicMaterial color="#facc15" /></mesh>}
                </>
            );
        } else if (tool === ToolType.MEASURE) {
            const dist = start.distanceTo(currentEnd);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <Line points={[start, currentEnd]} color={DIMENSION_COLOR} lineWidth={2} dashed dashScale={10} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(currentEnd.x - start.x);
             const depth = Math.abs(currentEnd.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;

             const p1 = start;
             const p2 = new THREE.Vector3(currentEnd.x, start.y, start.z);
             const p3 = currentEnd;
             const p4 = new THREE.Vector3(start.x, start.y, currentEnd.z);

             previewShape = <Line points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;

             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <Line points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else {
                 infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
             }
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}

            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}

            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip 
                    text={infoText || snapInfo!.type} 
                    position={cursorPos} 
                    type={snapInfo?.type} 
                 />
            )}

            {snapInfo?.guides?.map((guide, i) => (
                <Line key={i} points={guide} color="#a855f7" lineWidth={1} dashed dashScale={5} />
            ))}
        </group>
    );
};

const Viewport: React.FC = () => {
    const { shapes, selectedIds, selectShape, tool, transformMode, updateShape, setTransformMode } = useApp();
    const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp } = usePushPullManager();
    const { handleClick, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, drawPoints, cursorPos, snapInfo, isDragging: isDrawing } = useDrawingManager();
    const { scene } = useThree();

    // Combined handlers
    const onPointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPDown(e);
        else handleDrawDown(e);
    };

    const onPointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPMove(e);
    };

    const onPointerUp = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPUp();
        else handleDrawUp(e);
    };

    const onObjectPointerDown = (e: ThreeEvent<PointerEvent>, id: string) => {
        if (tool === ToolType.SELECT) {
            e.stopPropagation();
            selectShape(id, e.shiftKey);
        }
    };

    const selectedObject = shapes.find(s => s.id === selectedIds[selectedIds.length - 1]);

    return (
        <div className="w-full h-full bg-slate-900 cursor-crosshair">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 45 }}>
                <color attach="background" args={['#0f172a']} />

                <ambientLight intensity={0.5} />
                <directionalLight position={[10, 10, 5]} intensity={1} castShadow shadow-mapSize={[1024, 1024]} />
                <Environment preset="city" />

                <group 
                    onPointerDown={onPointerDown} 
                    onPointerMove={onPointerMove} 
                    onPointerUp={onPointerUp}
                    onClick={handleClick}
                >
                     {/* Grid */}
                    <Grid infiniteGrid sectionSize={1} cellSize={0.1} sectionColor="#475569" cellColor="#1e293b" fadeDistance={50} />

                    {/* Shapes */}
                    {shapes.map(shape => {
                         const isSelected = selectedIds.includes(shape.id);
                         const shape3D = createThreeShape(shape.points);
                         const extrudeSettings = { depth: shape.height, bevelEnabled: false };

                         return (
                             <group 
                                key={shape.id}
                                position={shape.position}
                                rotation={[0, shape.rotation, 0]}
                                scale={shape.scale}
                                userData={{ isShape: true, id: shape.id }}
                                onPointerDown={(e) => onObjectPointerDown(e, shape.id)}
                             >
                                {shape.type === 'dimension' ? (
                                    <Line 
                                        points={[
                                            new THREE.Vector3(shape.points[0].x, 0.05, shape.points[0].z), 
                                            new THREE.Vector3(shape.points[1].x, 0.05, shape.points[1].z)
                                        ]} 
                                        color={shape.color} 
                                        lineWidth={3} 
                                        dashed 
                                        dashScale={5} 
                                    />
                                ) : (
                                    <group rotation={[Math.PI / 2, 0, 0]}>
                                        <mesh castShadow receiveShadow>
                                            <extrudeGeometry args={[shape3D, extrudeSettings]} />
                                            <meshStandardMaterial 
                                                color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                                                transparent={shape.height < 0.02} 
                                                opacity={shape.height < 0.02 ? 0.8 : 1}
                                            />
                                        </mesh>
                                        {(isSelected || (ppState.hoveredShapeId === shape.id && tool === ToolType.PUSH_PULL)) && (
                                            <lineSegments>
                                                <edgesGeometry args={[new THREE.ExtrudeGeometry(shape3D, extrudeSettings)]} />
                                                <lineBasicMaterial color={ppState.hoveredShapeId === shape.id ? "#38bdf8" : "white"} />
                                            </lineSegments>
                                        )}
                                    </group>
                                )}
                             </group>
                         );
                    })}

                    {/* Drawing Visuals */}
                    <DrawingVisuals 
                        drawPoints={drawPoints} 
                        cursorPos={cursorPos} 
                        snapInfo={snapInfo} 
                        tool={tool} 
                    />

                    {/* Push Pull Highlight Face */}
                    {tool === ToolType.PUSH_PULL && ppState.mode === 'top' && ppState.hoveredShapeId && (() => {
                         const s = shapes.find(x => x.id === ppState.hoveredShapeId);
                         if (!s) return null;
                         const pts = s.points.map(p => new THREE.Vector3(p.x, -p.z, 0)); // Shape space
                         const shape = new THREE.Shape();
                         if(pts.length) {
                             shape.moveTo(pts[0].x, pts[0].y);
                             for(let i=1; i<pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
                         }
                         shape.closePath();

                         return (
                            <group 
                                position={s.position} 
                                rotation={[0, s.rotation, 0]} 
                                scale={s.scale}
                            >
                                <group position={[0, s.height, 0]} rotation={[Math.PI/2, 0, 0]}>
                                    <mesh>
                                        <shapeGeometry args={[shape]} />
                                        <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} depthTest={false} />
                                    </mesh>
                                </group>
                            </group>
                         )
                    })()}

                </group>

                <OrbitControls makeDefault enableDamping dampingFactor={0.1} />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
                </GizmoHelper>
            </Canvas>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number; // For side push/pull
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[]; // Snapshot of points before drag
    normal: THREE.Vector3; // Normal of the face we are pulling
}

// --- Geometry Helpers ---

const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const relX = worldP.x - shape.position[0];
    const relZ = worldP.z - shape.position[2];

    const rot = -shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xRot = relX * cos - relZ * sin;
    const zRot = relX * sin + relZ * cos;

    return {
        x: xRot / shape.scale[0],
        y: 0,
        z: zRot / shape.scale[2]
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;

  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;

  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;

  if (l2 === 0) return v;

  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));

  return new THREE.Vector3(
    v.x + t * vwx,
    v.y + t * vwy,
    v.z + t * vwz
  );
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    const distSq = (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
    return distSq;
};

// Check if point is on segment
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false;
    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false;
    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false;
    return true;
};

// Get intersection of two line segments (AB and CD)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel

    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return {
            x: p1.x + u * (p2.x - p1.x),
            y: 0,
            z: p1.z + u * (p2.z - p1.z)
        };
    }
    return null;
};

// Split a polygon by a line segment (cutStart -> cutEnd)
const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    // 1. Find intersections
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];

    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;

            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    if (intersections.length !== 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;

    // 2. Construct two new polygons
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }

    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);

    if (idx1 === -1 || idx2 === -1) return null;

    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);

    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];

    return [polyA, polyB];
};


// --- Geometry Snapping Logic ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;
    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));
    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) { minDiffX = diffX; alignX = pt.x; guideXSrc = pt; }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) { minDiffZ = diffZ; alignZ = pt.z; guideZSrc = pt; }
    }
    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;
        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        if (alignZ !== null && guideZSrc) guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        return { position: snappedPos, type: 'align', distance: 0, guides };
    }

    return bestSnap;
};

// --- Custom Hooks & Components ---

const usePushPullManager = () => {
    const { tool, updateShape, shapes } = useApp();
    const { camera, gl } = useThree();

    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = (e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const object = e.object;
        let curr: THREE.Object3D | null = object;
        let shapeId: string | null = null;
        while(curr) {
            if (curr.userData?.isShape) {
                shapeId = curr.userData.id;
                break;
            }
            curr = curr.parent;
        }
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;

        const intersection = e.intersections[0];
        if (!intersection || !intersection.face) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        if (worldNormal.y > 0.9) {
            return {
                mode: 'top',
                hoveredShapeId: shapeId,
                hoveredEdgeIndex: -1,
                normal: new THREE.Vector3(0, 1, 0)
            };
        }

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);

            let closestIndex = -1;
            let minDistSq = Infinity;

            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];

                const d2 = distToSegmentSquared(
                    new THREE.Vector3(unscaledX, 0, unscaledZ),
                    new THREE.Vector3(p1.x, 0, p1.z),
                    new THREE.Vector3(p2.x, 0, p2.z)
                );

                if (d2 < minDistSq) {
                    minDistSq = d2;
                    closestIndex = i;
                }
            }

            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return {
                    mode: 'side',
                    hoveredShapeId: shapeId,
                    hoveredEdgeIndex: closestIndex,
                    normal: flatNormal
                };
            }
        }

        return null;
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
            ), camera);

            if (ppState.mode === 'top') {
                const planeNormal = new THREE.Vector3();
                camera.getWorldDirection(planeNormal).setY(0).normalize(); 
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                   camera.getWorldDirection(new THREE.Vector3()).negate(), 
                   ppState.dragStartPoint
                );

                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    updateShape(shape.id, { height: newHeight });
                }

            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);

                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];

                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];

                    p1.x += dLocalX;
                    p1.z += dLocalZ;
                    p2.x += dLocalX;
                    p2.z += dLocalZ;

                    updateShape(shape.id, { points: newPoints });
                }
            }

        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ 
                    ...prev, 
                    mode: res.mode!, 
                    hoveredShapeId: res.hoveredShapeId!, 
                    hoveredEdgeIndex: res.hoveredEdgeIndex!,
                    normal: res.normal!
                }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();

        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
             ), camera);

             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                     camera.getWorldDirection(new THREE.Vector3()).negate(),
                     e.point
                 );
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }

             setPPState(prev => ({
                 ...prev,
                 dragStartPoint: startPoint,
                 originalHeight: shape.height,
                 originalPoints: JSON.parse(JSON.stringify(shape.points))
             }));
        }
    };

    const handlePointerUp = () => {
        if (isDragging) {
            setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [] }));
        }
    };

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes } = useApp();
    const { scene } = useThree();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
    }, [tool]);

    // Add Escape key handler
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setDrawPoints([]);
                setIsDragging(false);
                if (tool !== ToolType.SELECT) {
                    setTool(ToolType.SELECT);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, setTool]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;

        if (tool === ToolType.DRAW_RECT) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const width = Math.abs(end.x - start.x);
                 const depth = Math.abs(end.z - start.z);
                 if (width >= 0.01 && depth >= 0.01) {
                     const cx = (start.x + end.x) / 2;
                     const cz = (start.z + end.z) / 2;

                     const points = [
                         { x: -width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: depth/2 },
                         { x: -width/2, y: 0, z: depth/2 },
                     ];

                     addShape({
                         id: `rect-${Date.now()}`,
                         type: 'solid',
                         name: 'Area',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [cx, 0, cz],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_CIRCLE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createCirclePoints(radius);
                     addShape({
                         id: `circle-${Date.now()}`,
                         type: 'solid',
                         name: 'Circle',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [start.x, 0, start.z],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_ARC) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createArcPoints(radius);
                     const angle = Math.atan2(end.z - start.z, end.x - start.x);

                     addShape({
                        id: `arc-${Date.now()}`,
                        type: 'flat',
                        name: 'Door Swing',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, 0, start.z],
                        rotation: -angle, 
                        scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_LINE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

                 if (dist >= 0.01) {
                     let splitOccurred = false;

                     for (let i = shapes.length - 1; i >= 0; i--) {
                         const targetShape = shapes[i];
                         if (targetShape.type === 'dimension') continue;

                         const localStart = inverseTransformPoint(new THREE.Vector3(start.x, 0, start.z), targetShape);
                         const localEnd = inverseTransformPoint(new THREE.Vector3(end.x, 0, end.z), targetShape);

                         const splitResult = splitPolygonByLine(targetShape.points, localStart, localEnd);

                         if (splitResult) {
                             const [polyA, polyB] = splitResult;

                             const shapeA: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-a`,
                                 points: polyA,
                                 name: targetShape.name
                             };
                             const shapeB: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-b`,
                                 points: polyB,
                                 name: targetShape.name
                             };

                             replaceShapes([targetShape.id], [shapeA, shapeB]);
                             splitOccurred = true;
                             break;
                         }
                     }

                     if (!splitOccurred) {
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.2;

                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;

                        const halfL = dist / 2;
                        const halfW = thickness / 2;

                        const points = [
                            { x: -halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: halfW },
                            { x: -halfL, y: 0, z: halfW },
                        ];

                        addShape({
                           id: `wall-${Date.now()}`,
                           type: 'solid',
                           name: 'Wall',
                           points,
                           height: DEFAULT_HEIGHT,
                           color: DEFAULT_COLOR,
                           position: [cx, 0, cz],
                           rotation: -angle, 
                           scale: [1, 1, 1]
                        });
                     }
                     shapeCreated = true;
                     // Continuous Line: Set start point to end point for next segment
                     setDrawPoints([{ x: end.x, y: 0, z: end.z }]);
                     return; // Don't clear drawPoints
                 }
             }

        } else if (tool === ToolType.DRAW_POLY) {
             if (finalPoints.length >= 3) {
                 const cx = finalPoints.reduce((s, pt) => s + pt.x, 0) / finalPoints.length;
                 const cz = finalPoints.reduce((s, pt) => s + pt.z, 0) / finalPoints.length;

                 const localPoints = finalPoints.map(pt => ({ x: pt.x - cx, y: 0, z: pt.z - cz }));

                 addShape({
                    id: `poly-${Date.now()}`,
                    type: 'solid',
                    name: 'Polygon',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: DEFAULT_COLOR,
                    position: [cx, 0, cz],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.MEASURE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 addShape({
                    id: `dim-${Date.now()}`,
                    type: 'dimension',
                    name: 'Dimension',
                    points: [start, end],
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        }
        setDrawPoints([]);

        if (shapeCreated) {
            setTool(ToolType.SELECT);
        }

    }, [tool, addShape, wallThickness, setTool, shapes, replaceShapes]);

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        const groundNormal = new THREE.Vector3(0, 1, 0);
        const plane = new THREE.Plane(groundNormal, 0);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);

        if (hit) {
            const intersects = raycaster.intersectObjects(scene.children, true);
            const firstObjHit = intersects.find(i => i.object.userData?.isShape);

            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, firstObjHit);

            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }

            if (isDragging) {
                const currentP = { x: snap.position.x, y: 0, z: snap.position.z };

                 if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
                     setDrawPoints(prev => {
                         if (prev.length === 0) return [currentP];
                         return [prev[0], currentP];
                     });
                }
                // Removed DRAW_LINE from here since it uses click-click now
            }
        }
    });

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        if (e.button === 0) {
            e.stopPropagation();

            if (tool === ToolType.DRAW_POLY) {
                 const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                 if (drawPoints.length > 2) {
                     const first = drawPoints[0];
                     const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                     if (dist < SNAP_THRESHOLD) {
                         finishShape(drawPoints);
                         return;
                     }
                 }
                 setDrawPoints(prev => [...prev, p]);
            } 
            else if (tool === ToolType.DRAW_LINE) {
                // Continuous Line Logic (Click-Click)
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                if (drawPoints.length === 0) {
                     setDrawPoints([p]);
                } else {
                     // Finish segment
                     finishShape([drawPoints[0], p]);
                }
            }
            else {
                const p = { x: cursorPos.x, y: 0, z: cursorPos.z };
                setDrawPoints([p]);
                setIsDragging(true);
            }
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
         if (isDragging && e.button === 0) {
             e.stopPropagation();
             setIsDragging(false);

             // DRAW_LINE handled in PointerDown now
             if (tool !== ToolType.DRAW_POLY && tool !== ToolType.DRAW_LINE) {
                 if (drawPoints.length > 1) {
                     const start = drawPoints[0];
                     const end = drawPoints[drawPoints.length - 1];
                     const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (dist > 0.01) {
                        finishShape(drawPoints);
                     } else {
                         setDrawPoints([]);
                     }
                 }
             }
         }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        return;
    };

    return {
        handleClick,
        handlePointerDown,
        handlePointerUp,
        drawPoints,
        cursorPos,
        snapInfo,
        tool,
        isDragging
    };
};

const SnapIndicator: React.FC<{ position: THREE.Vector3, type: SnapType, snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none') return null;

    // Different colors for snap types
    const color = 
        type === 'vertex' ? '#ef4444' : // Red
        type === 'midpoint' ? '#06b6d4' : // Cyan
        type === 'edge' ? '#ef4444' : // Red
        type === 'face' ? '#3b82f6' : // Blue
        type === 'grid' ? '#64748b' : // Slate
        '#a855f7'; // Purple (Align)

    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' || type === 'midpoint' ? 0.08 : 0.05]} />
                <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
            </mesh>
            {type === 'midpoint' && (
                <mesh>
                    <boxGeometry args={[0.12, 0.12, 0.12]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
                </mesh>
            )}
             {snapEdge && (
                 <Line points={[snapEdge[0], snapEdge[1]]} color={color} lineWidth={2} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string, position: THREE.Vector3, type?: string }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.2, position.z]} center style={{ pointerEvents: 'none', whiteSpace: 'nowrap' }}>
            <div className={`px-2 py-1 rounded text-[10px] font-bold shadow-sm backdrop-blur-sm border border-white/20
                ${type === 'align' ? 'bg-purple-600/90 text-white' : 
                  type === 'midpoint' ? 'bg-cyan-600/90 text-white' :
                  type === 'vertex' ? 'bg-red-600/90 text-white' :
                  'bg-slate-800/90 text-white'}`}>
                {text}
            </div>
        </Html>
    );
};

const DrawingVisuals: React.FC<{ drawPoints: IPoint[], cursorPos: THREE.Vector3, snapInfo: SnapResult | null, tool: ToolType }> = ({ drawPoints, cursorPos, snapInfo, tool }) => {
    const { formatValue } = useApp();

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + 0.05, p.z));

    let previewShape: React.ReactElement | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];
        const currentEnd = points.length > 1 ? points[points.length - 1] : new THREE.Vector3(cursorPos.x, cursorPos.y + 0.05, cursorPos.z);

        if (tool === ToolType.DRAW_LINE) {
             const dist = start.distanceTo(currentEnd);
             infoText = `L: ${formatValue(dist)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_POLY) {
            const pointsToRender = [...points, currentEnd];

            if(points.length > 0) {
                 const last = points[points.length - 1];
                 const dist = last.distanceTo(currentEnd);
                 infoText = `L: ${formatValue(dist)}`;
            }

            let closeLoop = false;
            if (points.length > 2) {
                 if (start.distanceTo(currentEnd) < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                     closeLoop = true;
                 }
            }

            previewShape = (
                <>
                    <Line points={pointsToRender} color="black" lineWidth={2} />
                    {closeLoop && <mesh position={start}><sphereGeometry args={[0.15]} /><meshBasicMaterial color="#facc15" /></mesh>}
                </>
            );
        } else if (tool === ToolType.MEASURE) {
            const dist = start.distanceTo(currentEnd);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <Line points={[start, currentEnd]} color={DIMENSION_COLOR} lineWidth={2} dashed dashScale={10} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(currentEnd.x - start.x);
             const depth = Math.abs(currentEnd.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;

             const p1 = start;
             const p2 = new THREE.Vector3(currentEnd.x, start.y, start.z);
             const p3 = currentEnd;
             const p4 = new THREE.Vector3(start.x, start.y, currentEnd.z);

             previewShape = <Line points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;

             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <Line points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else {
                 infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
             }
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}

            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}

            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip 
                    text={infoText || snapInfo!.type} 
                    position={cursorPos} 
                    type={snapInfo?.type} 
                 />
            )}

            {snapInfo?.guides?.map((guide, i) => (
                <Line key={i} points={guide} color="#a855f7" lineWidth={1} dashed dashScale={5} />
            ))}
        </group>
    );
};

// --- SceneContent: Inner component where R3F hooks are safe ---
const SceneContent: React.FC = () => {
    const { shapes, selectedIds, selectShape, tool, transformMode, updateShape, setTransformMode } = useApp();
    const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp } = usePushPullManager();
    const { handleClick, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, drawPoints, cursorPos, snapInfo, isDragging: isDrawing } = useDrawingManager();
    const { scene } = useThree();

    // Combined handlers
    const onPointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPDown(e);
        else handleDrawDown(e);
    };

    const onPointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPMove(e);
    };

    const onPointerUp = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPUp();
        else handleDrawUp(e);
    };

    const onObjectPointerDown = (e: ThreeEvent<PointerEvent>, id: string) => {
        if (tool === ToolType.SELECT) {
            e.stopPropagation();
            selectShape(id, e.shiftKey);
        }
    };

    const selectedObject = shapes.find(s => s.id === selectedIds[selectedIds.length - 1]);

    return (
        <>
            <color attach="background" args={['#0f172a']} />

            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 10, 5]} intensity={1} castShadow shadow-mapSize={[1024, 1024]} />
            <Environment preset="city" />

            <group 
                onPointerDown={onPointerDown} 
                onPointerMove={onPointerMove} 
                onPointerUp={onPointerUp}
                onClick={handleClick}
            >
                    {/* Grid */}
                <Grid infiniteGrid sectionSize={1} cellSize={0.1} sectionColor="#475569" cellColor="#1e293b" fadeDistance={50} />

                {/* Shapes */}
                {shapes.map(shape => {
                        const isSelected = selectedIds.includes(shape.id);
                        const shape3D = createThreeShape(shape.points);
                        const extrudeSettings = { depth: shape.height, bevelEnabled: false };

                        return (
                            <group 
                            key={shape.id}
                            position={shape.position}
                            rotation={[0, shape.rotation, 0]}
                            scale={shape.scale}
                            userData={{ isShape: true, id: shape.id }}
                            onPointerDown={(e) => onObjectPointerDown(e, shape.id)}
                            >
                            {shape.type === 'dimension' ? (
                                <Line 
                                    points={[
                                        new THREE.Vector3(shape.points[0].x, 0.05, shape.points[0].z), 
                                        new THREE.Vector3(shape.points[1].x, 0.05, shape.points[1].z)
                                    ]} 
                                    color={shape.color} 
                                    lineWidth={3} 
                                    dashed 
                                    dashScale={5} 
                                />
                            ) : (
                                <group rotation={[Math.PI / 2, 0, 0]}>
                                    <mesh castShadow receiveShadow>
                                        <extrudeGeometry args={[shape3D, extrudeSettings]} />
                                        <meshStandardMaterial 
                                            color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                                            transparent={shape.height < 0.02} 
                                            opacity={shape.height < 0.02 ? 0.8 : 1}
                                        />
                                    </mesh>
                                    {(isSelected || (ppState.hoveredShapeId === shape.id && tool === ToolType.PUSH_PULL)) && (
                                        <lineSegments>
                                            <edgesGeometry args={[new THREE.ExtrudeGeometry(shape3D, extrudeSettings)]} />
                                            <lineBasicMaterial color={ppState.hoveredShapeId === shape.id ? "#38bdf8" : "white"} />
                                        </lineSegments>
                                    )}
                                </group>
                            )}
                            </group>
                        );
                })}

                {/* Drawing Visuals */}
                <DrawingVisuals 
                    drawPoints={drawPoints} 
                    cursorPos={cursorPos} 
                    snapInfo={snapInfo} 
                    tool={tool} 
                />

                {/* Push Pull Highlight Face */}
                {tool === ToolType.PUSH_PULL && ppState.mode === 'top' && ppState.hoveredShapeId && (() => {
                        const s = shapes.find(x => x.id === ppState.hoveredShapeId);
                        if (!s) return null;
                        const pts = s.points.map(p => new THREE.Vector3(p.x, -p.z, 0)); // Shape space
                        const shape = new THREE.Shape();
                        if(pts.length) {
                            shape.moveTo(pts[0].x, pts[0].y);
                            for(let i=1; i<pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
                        }
                        shape.closePath();

                        return (
                        <group 
                            position={s.position} 
                            rotation={[0, s.rotation, 0]} 
                            scale={s.scale}
                        >
                            <group position={[0, s.height, 0]} rotation={[Math.PI/2, 0, 0]}>
                                <mesh>
                                    <shapeGeometry args={[shape]} />
                                    <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} depthTest={false} />
                                </mesh>
                            </group>
                        </group>
                        )
                })()}

            </group>

            <OrbitControls makeDefault enableDamping dampingFactor={0.1} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full bg-slate-900 cursor-crosshair">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 45 }}>
                <SceneContent />
            </Canvas>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number; // For side push/pull
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[]; // Snapshot of points before drag
    normal: THREE.Vector3; // Normal of the face we are pulling
}

// --- Geometry Helpers ---

const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const relX = worldP.x - shape.position[0];
    const relZ = worldP.z - shape.position[2];

    const rot = -shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xRot = relX * cos - relZ * sin;
    const zRot = relX * sin + relZ * cos;

    return {
        x: xRot / shape.scale[0],
        y: 0,
        z: zRot / shape.scale[2]
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;

  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;

  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;

  if (l2 === 0) return v;

  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));

  return new THREE.Vector3(
    v.x + t * vwx,
    v.y + t * vwy,
    v.z + t * vwz
  );
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    const distSq = (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
    return distSq;
};

// Check if point is on segment
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false;
    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false;
    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false;
    return true;
};

// Get intersection of two line segments (AB and CD)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel

    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return {
            x: p1.x + u * (p2.x - p1.x),
            y: 0,
            z: p1.z + u * (p2.z - p1.z)
        };
    }
    return null;
};

// Split a polygon by a line segment (cutStart -> cutEnd)
const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    // 1. Find intersections
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];

    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;

            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    if (intersections.length !== 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;

    // 2. Construct two new polygons
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }

    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);

    if (idx1 === -1 || idx2 === -1) return null;

    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);

    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];

    return [polyA, polyB];
};


// --- Geometry Snapping Logic ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const topY = shape.position[1] + currentH;

        // Only snap to vertices that are relatively close in height to the cursor
        if (Math.abs(cursorPos.y - topY) > 0.5 && Math.abs(cursorPos.y - shape.position[1]) > 0.5) continue;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);

            // Check Base vertices
            if (Math.abs(cursorPos.y - shape.position[1]) < 0.5) {
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }

            // Check Top vertices
            if (Math.abs(currentH) > 0.001 && Math.abs(cursorPos.y - topY) < 0.5) {
                const worldPtTop = worldPt.clone().setY(topY);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const topY = shape.position[1] + currentH;
        const hasHeight = Math.abs(currentH) > 0.001;

        // Skip if cursor height is too far from shape bounds
        if (cursorPos.y < shape.position[1] - 0.5 || cursorPos.y > topY + 0.5) continue;

        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };

             // Check base edges
             if (Math.abs(cursorPos.y - shape.position[1]) < 0.5) checkSegment(p1, p2);

             // Check top edges
             if (hasHeight && Math.abs(cursorPos.y - topY) < 0.5) {
                 const p1Top = p1.clone().setY(topY);
                 const p2Top = p2.clone().setY(topY);
                 checkSegment(p1Top, p2Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         // Snapped to a face surface
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;
    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       // Only align with things on roughly the same level
       if(Math.abs(s.position[1] - cursorPos.y) < 1 || Math.abs((s.position[1] + s.height) - cursorPos.y) < 1) {
           s.points.forEach(p => candidates.push(transformPoint(p, s)));
       }
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));
    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) { minDiffX = diffX; alignX = pt.x; guideXSrc = pt; }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) { minDiffZ = diffZ; alignZ = pt.z; guideZSrc = pt; }
    }
    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;
        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        if (alignZ !== null && guideZSrc) guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        return { position: snappedPos, type: 'align', distance: 0, guides };
    }

    return bestSnap;
};

// --- Custom Hooks & Components ---

const usePushPullManager = () => {
    const { tool, updateShape, shapes } = useApp();
    const { camera, gl } = useThree();

    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = (e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const object = e.object;
        let curr: THREE.Object3D | null = object;
        let shapeId: string | null = null;
        while(curr) {
            if (curr.userData?.isShape) {
                shapeId = curr.userData.id;
                break;
            }
            curr = curr.parent;
        }
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;

        const intersection = e.intersections[0];
        if (!intersection || !intersection.face) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        if (worldNormal.y > 0.9) {
            return {
                mode: 'top',
                hoveredShapeId: shapeId,
                hoveredEdgeIndex: -1,
                normal: new THREE.Vector3(0, 1, 0)
            };
        }

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);

            let closestIndex = -1;
            let minDistSq = Infinity;

            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];

                const d2 = distToSegmentSquared(
                    new THREE.Vector3(unscaledX, 0, unscaledZ),
                    new THREE.Vector3(p1.x, 0, p1.z),
                    new THREE.Vector3(p2.x, 0, p2.z)
                );

                if (d2 < minDistSq) {
                    minDistSq = d2;
                    closestIndex = i;
                }
            }

            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return {
                    mode: 'side',
                    hoveredShapeId: shapeId,
                    hoveredEdgeIndex: closestIndex,
                    normal: flatNormal
                };
            }
        }

        return null;
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
            ), camera);

            if (ppState.mode === 'top') {
                const planeNormal = new THREE.Vector3();
                camera.getWorldDirection(planeNormal).setY(0).normalize(); 
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                   camera.getWorldDirection(new THREE.Vector3()).negate(), 
                   ppState.dragStartPoint
                );

                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    updateShape(shape.id, { height: newHeight });
                }

            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);

                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];

                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];

                    p1.x += dLocalX;
                    p1.z += dLocalZ;
                    p2.x += dLocalX;
                    p2.z += dLocalZ;

                    updateShape(shape.id, { points: newPoints });
                }
            }

        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ 
                    ...prev, 
                    mode: res.mode!, 
                    hoveredShapeId: res.hoveredShapeId!, 
                    hoveredEdgeIndex: res.hoveredEdgeIndex!,
                    normal: res.normal!
                }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();

        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2(
                (e.clientX / gl.domElement.clientWidth) * 2 - 1,
                -(e.clientY / gl.domElement.clientHeight) * 2 + 1
             ), camera);

             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(
                     camera.getWorldDirection(new THREE.Vector3()).negate(),
                     e.point
                 );
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }

             setPPState(prev => ({
                 ...prev,
                 dragStartPoint: startPoint,
                 originalHeight: shape.height,
                 originalPoints: JSON.parse(JSON.stringify(shape.points))
             }));
        }
    };

    const handlePointerUp = () => {
        if (isDragging) {
            setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [] }));
        }
    };

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes } = useApp();
    const { scene } = useThree();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
    }, [tool]);

    // Add Escape key handler
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setDrawPoints([]);
                setIsDragging(false);
                if (tool !== ToolType.SELECT) {
                    setTool(ToolType.SELECT);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, setTool]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;

        // Determine the base height for the new shape based on the first point's Y
        // This supports drawing on top of other objects
        const baseHeight = finalPoints.length > 0 ? finalPoints[0].y : 0;

        if (tool === ToolType.DRAW_RECT) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const width = Math.abs(end.x - start.x);
                 const depth = Math.abs(end.z - start.z);
                 if (width >= 0.01 && depth >= 0.01) {
                     const cx = (start.x + end.x) / 2;
                     const cz = (start.z + end.z) / 2;

                     const points = [
                         { x: -width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: -depth/2 },
                         { x: width/2, y: 0, z: depth/2 },
                         { x: -width/2, y: 0, z: depth/2 },
                     ];

                     addShape({
                         id: `rect-${Date.now()}`,
                         type: 'solid',
                         name: 'Area',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [cx, baseHeight, cz],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_CIRCLE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createCirclePoints(radius);
                     addShape({
                         id: `circle-${Date.now()}`,
                         type: 'solid',
                         name: 'Circle',
                         points,
                         height: DEFAULT_HEIGHT,
                         color: FLAT_COLOR,
                         position: [start.x, baseHeight, start.z],
                         rotation: 0,
                         scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_ARC) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                 if (radius >= 0.01) {
                     const points = createArcPoints(radius);
                     const angle = Math.atan2(end.z - start.z, end.x - start.x);

                     addShape({
                        id: `arc-${Date.now()}`,
                        type: 'flat',
                        name: 'Door Swing',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, baseHeight, start.z],
                        rotation: -angle, 
                        scale: [1, 1, 1]
                     });
                     shapeCreated = true;
                 }
             }
        } else if (tool === ToolType.DRAW_LINE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1]; 
                 const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

                 if (dist >= 0.01) {
                     let splitOccurred = false;

                     for (let i = shapes.length - 1; i >= 0; i--) {
                         const targetShape = shapes[i];
                         if (targetShape.type === 'dimension') continue;

                         // VITAL: Only split if the line is drawn at the same height as the shape's top or bottom
                         const shapeTop = targetShape.position[1] + targetShape.height * targetShape.scale[1];
                         const shapeBase = targetShape.position[1];
                         const isAtTop = Math.abs(start.y - shapeTop) < 0.05;
                         const isAtBase = Math.abs(start.y - shapeBase) < 0.05;

                         if (!isAtTop && !isAtBase) continue;

                         const localStart = inverseTransformPoint(new THREE.Vector3(start.x, 0, start.z), targetShape);
                         const localEnd = inverseTransformPoint(new THREE.Vector3(end.x, 0, end.z), targetShape);

                         const splitResult = splitPolygonByLine(targetShape.points, localStart, localEnd);

                         if (splitResult) {
                             const [polyA, polyB] = splitResult;

                             const shapeA: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-a`,
                                 points: polyA,
                                 name: targetShape.name
                             };
                             const shapeB: IShape = {
                                 ...targetShape,
                                 id: `split-${Date.now()}-b`,
                                 points: polyB,
                                 name: targetShape.name
                             };

                             replaceShapes([targetShape.id], [shapeA, shapeB]);
                             splitOccurred = true;
                             break;
                         }
                     }

                     if (!splitOccurred) {
                        const angle = Math.atan2(end.z - start.z, end.x - start.x);
                        const thickness = wallThickness || 0.2;

                        const cx = (start.x + end.x) / 2;
                        const cz = (start.z + end.z) / 2;

                        const halfL = dist / 2;
                        const halfW = thickness / 2;

                        const points = [
                            { x: -halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: -halfW },
                            { x: halfL, y: 0, z: halfW },
                            { x: -halfL, y: 0, z: halfW },
                        ];

                        addShape({
                           id: `wall-${Date.now()}`,
                           type: 'solid',
                           name: 'Wall',
                           points,
                           height: DEFAULT_HEIGHT,
                           color: DEFAULT_COLOR,
                           position: [cx, baseHeight, cz],
                           rotation: -angle, 
                           scale: [1, 1, 1]
                        });
                     }
                     shapeCreated = true;
                     // Continuous Line: Set start point to end point for next segment (preserve Y)
                     setDrawPoints([{ x: end.x, y: baseHeight, z: end.z }]);
                     return; // Don't clear drawPoints
                 }
             }

        } else if (tool === ToolType.DRAW_POLY) {
             if (finalPoints.length >= 3) {
                 const cx = finalPoints.reduce((s, pt) => s + pt.x, 0) / finalPoints.length;
                 const cz = finalPoints.reduce((s, pt) => s + pt.z, 0) / finalPoints.length;

                 const localPoints = finalPoints.map(pt => ({ x: pt.x - cx, y: 0, z: pt.z - cz }));

                 addShape({
                    id: `poly-${Date.now()}`,
                    type: 'solid',
                    name: 'Polygon',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: DEFAULT_COLOR,
                    position: [cx, baseHeight, cz],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.MEASURE) {
             if (finalPoints.length >= 2) {
                 const start = finalPoints[0];
                 const end = finalPoints[finalPoints.length - 1];
                 addShape({
                    id: `dim-${Date.now()}`,
                    type: 'dimension',
                    name: 'Dimension',
                    points: [start, end],
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0], // Dims are special, might need better Y handling, but 0 is usually safe or overlay
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 shapeCreated = true;
             }
        }
        setDrawPoints([]);

        if (shapeCreated) {
            setTool(ToolType.SELECT);
        }

    }, [tool, addShape, wallThickness, setTool, shapes, replaceShapes]);

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        // 1. First check if we are hovering over an existing object to draw on top of it
        const intersects = raycaster.intersectObjects(scene.children, true);
        const shapeHit = intersects.find(i => i.object.userData?.isShape);

        let target = new THREE.Vector3();
        let intersectedObj = undefined;

        if (shapeHit) {
             // If drawing, we want to snap to the surface of the object
             target.copy(shapeHit.point);
             intersectedObj = shapeHit;
             // Ensure we are snapping to the exact plane height if close
             const shapeId = shapeHit.object.userData.id;
             const shape = shapes.find(s => s.id === shapeId);
             if (shape) {
                 const topY = shape.position[1] + shape.height * shape.scale[1];
                 if (Math.abs(target.y - topY) < 0.1) target.y = topY;
                 else if (Math.abs(target.y - shape.position[1]) < 0.1) target.y = shape.position[1];
             }
        } else {
             // Fallback to ground plane
            const groundNormal = new THREE.Vector3(0, 1, 0);
            const plane = new THREE.Plane(groundNormal, 0);
            raycaster.ray.intersectPlane(plane, target);
        }

        // Only proceed if we hit something (object or ground)
        if (target) {
            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, intersectedObj);

            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }

            if (isDragging) {
                const currentP = { x: snap.position.x, y: snap.position.y, z: snap.position.z };

                 if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE) {
                     setDrawPoints(prev => {
                         if (prev.length === 0) return [currentP];
                         return [prev[0], currentP];
                     });
                }
                else if (tool === ToolType.DRAW_LINE) {
                     setDrawPoints(prev => {
                         if (prev.length === 0) return [currentP];
                         return [prev[0], currentP];
                     });
                }
            }
        }
    });

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        if (e.button === 0) {
            e.stopPropagation();

            if (tool === ToolType.DRAW_POLY) {
                 const p = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
                 if (drawPoints.length > 2) {
                     const first = drawPoints[0];
                     const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                     // Check if closing loop on same height
                     if (dist < SNAP_THRESHOLD && Math.abs(p.y - first.y) < 0.1) {
                         finishShape(drawPoints);
                         return;
                     }
                 }
                 setDrawPoints(prev => [...prev, p]);
            } 
            else if (tool === ToolType.DRAW_LINE) {
                // Continuous Line Logic (Click-Click)
                const p = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
                if (drawPoints.length === 0) {
                     setDrawPoints([p]);
                } else {
                     // Finish segment
                     finishShape([drawPoints[0], p]);
                }
            }
            else {
                const p = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
                setDrawPoints([p]);
                setIsDragging(true);
            }
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
         if (isDragging && e.button === 0) {
             e.stopPropagation();
             setIsDragging(false);

             // DRAW_LINE handled in PointerDown now
             if (tool !== ToolType.DRAW_POLY && tool !== ToolType.DRAW_LINE) {
                 if (drawPoints.length > 1) {
                     const start = drawPoints[0];
                     const end = drawPoints[drawPoints.length - 1];
                     const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (dist > 0.01) {
                        finishShape(drawPoints);
                     } else {
                         setDrawPoints([]);
                     }
                 }
             }
         }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        return;
    };

    return {
        handleClick,
        handlePointerDown,
        handlePointerUp,
        drawPoints,
        cursorPos,
        snapInfo,
        tool,
        isDragging
    };
};

const SnapIndicator: React.FC<{ position: THREE.Vector3, type: SnapType, snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none') return null;

    // Different colors for snap types
    const color = 
        type === 'vertex' ? '#ef4444' : // Red
        type === 'midpoint' ? '#06b6d4' : // Cyan
        type === 'edge' ? '#ef4444' : // Red
        type === 'face' ? '#3b82f6' : // Blue
        type === 'grid' ? '#64748b' : // Slate
        '#a855f7'; // Purple (Align)

    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' || type === 'midpoint' ? 0.08 : 0.05]} />
                <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
            </mesh>
            {type === 'midpoint' && (
                <mesh>
                    <boxGeometry args={[0.12, 0.12, 0.12]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
                </mesh>
            )}
             {snapEdge && (
                 <Line points={[snapEdge[0], snapEdge[1]]} color={color} lineWidth={2} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string, position: THREE.Vector3, type?: string }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.2, position.z]} center style={{ pointerEvents: 'none', whiteSpace: 'nowrap' }}>
            <div className={`px-2 py-1 rounded text-[10px] font-bold shadow-sm backdrop-blur-sm border border-white/20
                ${type === 'align' ? 'bg-purple-600/90 text-white' : 
                  type === 'midpoint' ? 'bg-cyan-600/90 text-white' :
                  type === 'vertex' ? 'bg-red-600/90 text-white' :
                  'bg-slate-800/90 text-white'}`}>
                {text}
            </div>
        </Html>
    );
};

const DrawingVisuals: React.FC<{ drawPoints: IPoint[], cursorPos: THREE.Vector3, snapInfo: SnapResult | null, tool: ToolType }> = ({ drawPoints, cursorPos, snapInfo, tool }) => {
    const { formatValue } = useApp();

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + 0.05, p.z));

    let previewShape: React.ReactElement | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];
        const currentEnd = points.length > 1 ? points[points.length - 1] : new THREE.Vector3(cursorPos.x, cursorPos.y + 0.05, cursorPos.z);

        if (tool === ToolType.DRAW_LINE) {
             const dist = start.distanceTo(currentEnd);
             infoText = `L: ${formatValue(dist)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_POLY) {
            const pointsToRender = [...points, currentEnd];

            if(points.length > 0) {
                 const last = points[points.length - 1];
                 const dist = last.distanceTo(currentEnd);
                 infoText = `L: ${formatValue(dist)}`;
            }

            let closeLoop = false;
            if (points.length > 2) {
                 if (start.distanceTo(currentEnd) < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                     closeLoop = true;
                 }
            }

            previewShape = (
                <>
                    <Line points={pointsToRender} color="black" lineWidth={2} />
                    {closeLoop && <mesh position={start}><sphereGeometry args={[0.15]} /><meshBasicMaterial color="#facc15" /></mesh>}
                </>
            );
        } else if (tool === ToolType.MEASURE) {
            const dist = start.distanceTo(currentEnd);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <Line points={[start, currentEnd]} color={DIMENSION_COLOR} lineWidth={2} dashed dashScale={10} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(currentEnd.x - start.x);
             const depth = Math.abs(currentEnd.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;

             const p1 = start;
             const p2 = new THREE.Vector3(currentEnd.x, start.y, start.z);
             const p3 = currentEnd;
             const p4 = new THREE.Vector3(start.x, start.y, currentEnd.z);

             previewShape = <Line points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;

             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <Line points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <Line points={[start, currentEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else {
                 infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
             }
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}

            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}

            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip 
                    text={infoText || snapInfo!.type} 
                    position={cursorPos} 
                    type={snapInfo?.type} 
                 />
            )}

            {snapInfo?.guides?.map((guide, i) => (
                <Line key={i} points={guide} color="#a855f7" lineWidth={1} dashed dashScale={5} />
            ))}
        </group>
    );
};

// --- SceneContent: Inner component where R3F hooks are safe ---
const SceneContent: React.FC = () => {
    const { shapes, selectedIds, selectShape, tool, transformMode, updateShape, setTransformMode } = useApp();
    const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp } = usePushPullManager();
    const { handleClick, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, drawPoints, cursorPos, snapInfo, isDragging: isDrawing } = useDrawingManager();
    const { scene } = useThree();

    // Combined handlers
    const onPointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPDown(e);
        else handleDrawDown(e);
    };

    const onPointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPMove(e);
    };

    const onPointerUp = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.PUSH_PULL) handlePPUp();
        else handleDrawUp(e);
    };

    const onObjectPointerDown = (e: ThreeEvent<PointerEvent>, id: string) => {
        if (tool === ToolType.SELECT) {
            e.stopPropagation();
            selectShape(id, e.shiftKey);
        }
    };

    const selectedObject = shapes.find(s => s.id === selectedIds[selectedIds.length - 1]);

    return (
        <>
            <color attach="background" args={['#0f172a']} />

            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 10, 5]} intensity={1} castShadow shadow-mapSize={[1024, 1024]} />
            <Environment preset="city" />

            <group 
                onPointerDown={onPointerDown} 
                onPointerMove={onPointerMove} 
                onPointerUp={onPointerUp}
                onClick={handleClick}
            >
                    {/* Grid */}
                <Grid infiniteGrid sectionSize={1} cellSize={0.1} sectionColor="#475569" cellColor="#1e293b" fadeDistance={50} />

                {/* Shapes */}
                {shapes.map(shape => {
                        const isSelected = selectedIds.includes(shape.id);
                        const shape3D = createThreeShape(shape.points);
                        const extrudeSettings = { depth: shape.height, bevelEnabled: false };

                        return (
                            <group 
                            key={shape.id}
                            position={shape.position}
                            rotation={[0, shape.rotation, 0]}
                            scale={shape.scale}
                            userData={{ isShape: true, id: shape.id }}
                            onPointerDown={(e) => onObjectPointerDown(e, shape.id)}
                            >
                            {shape.type === 'dimension' ? (
                                <Line 
                                    points={[
                                        new THREE.Vector3(shape.points[0].x, 0.05, shape.points[0].z), 
                                        new THREE.Vector3(shape.points[1].x, 0.05, shape.points[1].z)
                                    ]} 
                                    color={shape.color} 
                                    lineWidth={3} 
                                    dashed 
                                    dashScale={5} 
                                />
                            ) : (
                                <group rotation={[Math.PI / 2, 0, 0]}>
                                    <mesh castShadow receiveShadow>
                                        <extrudeGeometry args={[shape3D, extrudeSettings]} />
                                        <meshStandardMaterial 
                                            color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                                            transparent={shape.height < 0.02} 
                                            opacity={shape.height < 0.02 ? 0.8 : 1}
                                        />
                                    </mesh>
                                    {(isSelected || (ppState.hoveredShapeId === shape.id && tool === ToolType.PUSH_PULL)) && (
                                        <lineSegments>
                                            <edgesGeometry args={[new THREE.ExtrudeGeometry(shape3D, extrudeSettings)]} />
                                            <lineBasicMaterial color={ppState.hoveredShapeId === shape.id ? "#38bdf8" : "white"} />
                                        </lineSegments>
                                    )}
                                </group>
                            )}
                            </group>
                        );
                })}

                {/* Drawing Visuals */}
                <DrawingVisuals 
                    drawPoints={drawPoints} 
                    cursorPos={cursorPos} 
                    snapInfo={snapInfo} 
                    tool={tool} 
                />

                {/* Push Pull Highlight Face */}
                {tool === ToolType.PUSH_PULL && ppState.mode === 'top' && ppState.hoveredShapeId && (() => {
                        const s = shapes.find(x => x.id === ppState.hoveredShapeId);
                        if (!s) return null;
                        const pts = s.points.map(p => new THREE.Vector3(p.x, -p.z, 0)); // Shape space
                        const shape = new THREE.Shape();
                        if(pts.length) {
                            shape.moveTo(pts[0].x, pts[0].y);
                            for(let i=1; i<pts.length; i++) shape.lineTo(pts[i].x, pts[i].y);
                        }
                        shape.closePath();

                        return (
                        <group 
                            position={s.position} 
                            rotation={[0, s.rotation, 0]} 
                            scale={s.scale}
                        >
                            <group position={[0, s.height, 0]} rotation={[Math.PI/2, 0, 0]}>
                                <mesh>
                                    <shapeGeometry args={[shape]} />
                                    <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} depthTest={false} />
                                </mesh>
                            </group>
                        </group>
                        )
                })()}

            </group>

            <OrbitControls makeDefault enableDamping dampingFactor={0.1} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full bg-slate-900 cursor-crosshair">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 45 }}>
                <SceneContent />
            </Canvas>
        </div>
    );
};

export default Viewport;
